const size_t n = internal_key.size();
if (n < 8) return false;
const uint64_t num = leveldb::DecodeFixed64(internal_key.data() + n - 8);
*user_key = Slice(internal_key.data(), n - 8);
*sequence = num >> 8;
*type = static_cast<uint8_t>(num & 0xff);
return *type <= leveldb::kValueTypeForSeek;

